check(S::packages('20(1kg) 250g(60) 500g(30)')===S::packages('1kg(20) 250g(60) 500g(30)'),'Count outside parentheses');
check(S::packages('500ml(1) & 500ml(1)')===['ml:500'=>2],'Ampersand joins explicit sizes');
foreach(['1kg(20, 500g(4)','49','1.5 packs × 100g','-2 packs × 500ml','95 packs × 100g — 5 missing','95 packs × 100g — uncertain','99 packs * 20 units totals 1970','99 packs * 20 units totals 1980 extra','1.5 units']as$text)check(S::packages($text)===null,'Do not guess ambiguous output: '.$text);
check(S::packages('8 packs × 250 g; 2 packs × 500 g —')===S::packages('250g(8) 500g(2)'),'Trailing editor separator');
check(S::packages('95packs × 100 g; 4packs × 500 g — T')===S::packages('100g(95) 500g(4)'),'Truncated nonnumeric total marker');
check(S::packages('4 packs × 500 ml; 3 packs × 1 L, 100ml-2 packs , 50ml- 1 pack')===S::packages('500ml(4) 1L(3) 100ml(2) 50ml(1)'),'Mixed explicit Neem formats');
check(S::packages('99 packs * 20 units totals 1980')===['unit:20'=>99],'Multipack preserves package count');
check(S::packages('49',S::packages('49 units'))===['unit:1'=>49.0],'Bare count inherits explicit individual unit context only');
check(S::packages('49',S::packages('500ml(49)'))===null,'Bare count does not infer bottle size');
check(S::packages('',S::packages('49 units'))===null,'Missing actual is never copied from plan');
check(S::packages('5 units')===['unit:1'=>5.0],'Pieces counted as units');
foreach(['50','50kg unknown','10 bags','-5kg']as$text)check(S::packages($text)===null,'Ambiguous input: '.$text);
check(S::accuracy(S::packages('100g (5)'),S::packages('500g (1)'))==='mixed','Equal weight is not equal package mix');
check(S::accuracy(S::packages('100g (5)'),S::packages('100g (4)'))==='less','Underpacked');
check(S::accuracy(S::packages('100g (5)'),S::packages('100g (6)'))==='more','Overpacked');
foreach(['website','packed_label_needed','label_created','done_needs_label','correction_needed']as$s)check(!S::finished($s),'Not fully finished: '.$s);
$item=['id'=>1,'item_name'=>'Chia','assigned_employee_id'=>7,'packing_status'=>'done','priority'=>'critical','quantity_planned'=>'100g (100), 500g (80)','quantity_packed'=>'100g (100), 500g (80)','date_loaded'=>'2026-10-02 16:00:00','date_started'=>'2026-10-02 16:30:00','date_completed'=>'2026-10-05 09:00:00'];
$event=static fn($at,$field,$before,$after,$actor=7)=>compact('at','field','before','after','actor');
$events=[1=>[$event('2026-10-02 16:30:00','packing_status','not_started','packing'),$event('2026-10-03 10:00:00','quantity_packed','0','100g (50)'),$event('2026-10-03 11:00:00','quantity_packed','100g (50)','100g (100)'),$event('2026-10-05 08:30:00','quantity_packed','100g (100)','100g (100), 500g (80)'),$event('2026-10-05 09:00:00','packing_status','packing','done')]];
$clock=new Clock([]);$build=static fn($i,$ev,$owners=[],$ex=[],$from='2026-10-01 00:00:00',$to='2026-10-31 23:59:59')=>S::build($i,$ev,$owners,$ex,7,$from,$to,$clock);
$s=$build([$item],$events);check($s['completed']===1&&$s['packages']===180&&$s['kg']==50,'Count final package snapshot once');
check($s['timing']['median_minutes']==330,'Fri half-hour, Sat four hours, Mon one hour; Sunday excluded');
check($s['quantity_updates']['2026-10-03']['added']==100,'Daily cumulative 50 then100 adds100, not150');
check($s['accuracy_percent']==100&&$s['responsibility_review']===0,'Full process assigned packer');
check($s['priorities']===[],'Finished batches are not still in the priority queue');
$old=$build([$item],$events,[],[],'2026-10-01 00:00:00','2026-10-03 23:59:59');check($old['completed']===0&&$old['open']===1&&$old['progress_sizes']['g:100']==100,'Historical snapshot before completion, no future quantity');
check($old['priorities']['critical']===1,'Historical priority queue includes unfinished batch');
$blocked=['employee_id'=>7,'effective_from'=>'2026-10-03 09:00:00','effective_to'=>'2026-10-03 11:00:00'];
$s=$build([$item],$events,[],[$blocked,$blocked]);check($s['timing']['median_minutes']==210&&$s['evidence'][0]['excluded_minutes']==120,'Overlapping confirmed blockers deducted once');
$e=$events;$e[1][]=$event('2026-10-06 09:00:00','packing_status','done','packing');$e[1][]=$event('2026-10-06 10:00:00','packing_status','packing','done');
$s=$build([$item],$e);check($s['reopened']===1&&$s['completed']===1&&$s['packages']===180,'Reopened completion does not duplicate output');
$noActor=$events;foreach($noActor[1]as&$r)$r['actor']=0;unset($r);$s=$build([$item],$noActor);check($s['timing']['median_minutes']===330.0&&$s['responsibility_review']===1,'Missing actor must not erase timing');
$other=$item;$other['assigned_employee_id']=8;$s=$build([$other],$events);check($s['items']===0,'No other packer work');
$assignment=[1=>[['at'=>'2026-10-07 08:00:00','old'=>7,'new'=>8]]];$s=$build([$other],$events,$assignment);check($s['completed']===1,'Later reassignment preserves earlier completion responsibility');
$earlyAssignment=[1=>[['at'=>'2026-10-04 08:00:00','old'=>7,'new'=>8]]];$s=$build([$other],$events,$earlyAssignment);check($s['completed']===0&&$s['items']===0,'Earlier activity does not claim colleague completion');
$startBefore=$item;$startBefore['date_loaded']='2026-09-01 08:00:00';$s=$build([$startBefore],$events);check($s['completed']===1,'Carry-in batch completion included');
$noteEvents=$events;$noteEvents[1][]=$event('2026-10-04 10:00:00','notes','','waiting for labels');$s=$build([$item],$noteEvents);check($s['notes']===1&&$s['note_reasons']['label']===1,'Notes diagnostic only');
check(!array_key_exists('score',$s)&&!array_key_exists('stalled',$s),'No grade or stalled flag');

// Business Health must sum the same actual output as the employee profile,
// ignoring cached workload quantities, including historical corrections.
$actual=$item;$actual['quantity_packed']='100g (44), 500ml (5)';
$actual['workload_package_count']=51;$actual['workload_weight_grams']=9000;
$s=$build([$actual],$events);
check(array_sum(array_column($s['output_daily'],'packages'))===$s['packages'],'Daily output and profile use one package total');
check(abs(array_sum(array_column($s['output_daily'],'weight_kg'))-$s['kg'])<0.0001,'Daily weight equals profile');
check(abs(array_sum(array_column($s['output_daily'],'volume_l'))-$s['litres'])<0.0001,'Daily volume equals profile');
check($s['packages']===49&&$s['kg']===4.4&&$s['litres']===2.5,'Stored workload estimates do not replace recorded output');
$s=$build([$other],$events,$assignment);
check(array_sum(array_column($s['output_daily'],'items'))===1,'Daily output preserves historical owner');
$s=$build([$item],$events,[],[],'2026-10-01 00:00:00','2026-10-03 23:59:59');
check($s['output_daily']===[],'Unfinished batches never enter completed chart');
$s=$build([$item],$e);
check(array_sum(array_column($s['output_daily'],'items'))===1,'Reopening does not duplicate daily output');
$oil=$item;$oil['quantity_planned']=$oil['quantity_packed']='186 packs × 500 ml; 5 packs × 1 L; 40 packs × 100 ml; 14 packs × 50 ml';
$s=$build([$oil],$events);
check($s['packages']===245&&$s['litres']===102.7&&$s['accuracy_percent']===100.0,'Historical castor breakdown counts packages and litres');
check(array_sum(array_column($s['output_daily'],'packages'))===245,'Business daily output receives corrected quantities');
$tea=$item;$tea['quantity_planned']='50 packs × 20 units';$tea['quantity_packed']='99 packs * 20 units totals 1980';$s=$build([$tea],[]);
check($s['packages']===99&&array_sum(array_column($s['output_daily'],'units'))==1980,'99 tea bag packages and 1980 individual pieces are separate');
check($s['accuracy']['more']===1,'Multipack comparison preserves package mix');
$bottles=$item;$bottles['quantity_planned']='49 units';$bottles['quantity_packed']='49';$s=$build([$bottles],[]);
check($s['quantity_known']===1&&$s['packages']==49&&$s['accuracy']['exact']===1,'Applicator actual inherits only explicitly planned unit');
$turmeric=$item;$turmeric['quantity_planned']='1kg(2) 100g(30)';$turmeric['quantity_packed']='';$s=$build([$turmeric],[]);
check($s['completed']===1&&$s['quantity_known']===0&&$s['packages']===0&&$s['accuracy']['unknown']===1,'Finished turmeric counted without invented actual output');
$soap=$item;$soap['quantity_planned']='1kg(2) 500g(4) 250g(2)';$soap['quantity_packed']='1kg(20, 500g(4), 250g(2)';$s=$build([$soap],[]);
check($s['quantity_known']===0,'Broken bracket remains unknown rather than inventing twenty packs');
$soap['quantity_packed']='1kg(2), 500g(4), 250g(2)';$s=$build([$soap],[]);
check($s['quantity_known']===1&&$s['packages']===8&&$s['kg']===4.5,'Owner-confirmed soap correction counts eight packs and 4.5kg');
$handoff=$item;$handoff['packing_website_confirmed']=1;$handoff['packing_website_completed_at']='2026-10-05 09:00:00';$handoff['frontdesk_website_updated']=1;$handoff['frontdesk_website_updated_at']='2026-10-03 10:00:00';
$s=$build([$handoff],$events);
check($s['website_review']===1&&$s['website_waiting']===0&&$s['website_updated']===0,'Earlier website update is a conflict, not waiting');
check($s['evidence'][0]['website_wait_minutes']===null&&$s['timing']['website_median_minutes']===null,'Conflicts cannot generate delay or median');
$handoff['frontdesk_website_updated_at']='2026-10-05 10:00:00';$s=$build([$handoff],$events);
check($s['website_updated']===1&&$s['website_review']===0&&$s['timing']['website_median_minutes']===60.0,'Valid handoff still measured');
$handoff['frontdesk_website_updated_at']=null;$s=$build([$handoff],$events);
check($s['website_review']===1&&$s['website_waiting']===0,'Confirmed update missing timestamp needs review');
$handoff['frontdesk_website_updated']=0;$s=$build([$handoff],$events);
check($s['website_waiting']===1&&$s['website_review']===0,'Unconfirmed update genuinely waits');
$handoff['packing_website_completed_at']='2026-11-02 08:00:00';$handoff['frontdesk_website_updated_at']='2026-11-02 09:00:00';$handoff['frontdesk_website_updated_by']=9;$s=$build([$handoff],$events);
check($s['evidence'][0]['website_ready_at']===null&&$s['evidence'][0]['website_updated_at']===null&&$s['evidence'][0]['website_updated_by']===null,'Future handoff evidence is not displayed in earlier month');
echo "PASS: $checks Packing List workload, quantity, historical timing and attribution checks\n";
